def solve_nonogram(n, m, row_constraints, col_constraints):
    def is_valid(board):
        for i in range(n):
            segments = []
            count = 0
            for j in range(m):
                if board[i][j] == '*':
                    count += 1
                elif count > 0:
                    segments.append(count)
                    count = 0
            if count > 0:
                segments.append(count)
            if segments != row_constraints[i]:
                return False

        for j in range(m):
            segments = []
            count = 0
            for i in range(n):
                if board[i][j] == '*':
                    count += 1
                elif count > 0:
                    segments.append(count)
                    count = 0
            if count > 0:
                segments.append(count)
            if segments != col_constraints[j]:
                return False

        return True

    def backtrack(board, row, col):
        if row == n:
            return is_valid(board)
        if col == m:
            return backtrack(board, row + 1, 0)

        board[row][col] = '.'
        if backtrack(board, row, col + 1):
            return True

        board[row][col] = '*'
        if backtrack(board, row, col + 1):
            return True

        board[row][col] = '.'
        return False

    board = [['.' for _ in range(m)] for _ in range(n)]
    backtrack(board, 0, 0)
    return [''.join(row) for row in board]

